function updateAccountSession(){cloudArtifactLibrary?.refresh();if(homeService?.user&&homeService.user.id!==workspaceSession.user?.id){homeRequest++;homeService={cap:homeService.cap,user:null};}updateProfile();onlineWorkspaceSessionChanged(workspaceSession.user);accountDraftSessionChanged(workspaceSession.user);thesisOnlineSessionChanged(workspaceSession.user);questionnaireSessionChanged(workspaceSession.user);const panel=$('#workspace-account-session');if(panel){const form=panel.querySelector('#account-name-form'),input=form?.querySelector('#account-name'),pending=form?.dataset.userId===workspaceSession.user?.id&&input?.value!==form?.dataset.initialName?input.value:null;panel.innerHTML=sessionPanel();if(pending!==null&&panel.querySelector('#account-name'))panel.querySelector('#account-name').value=pending;}const security=$('#account-security');if(security)security.innerHTML=securityPanel();if($('.home-refresh'))refreshHomePanels();if(workspaceSession.user&&!routeInfo().params.has('scope')&&['projects','assets','tasks','membership','help'].includes(routeInfo().parts[0])&&$('.workspace-scope-tabs a.active')?.getAttribute('href')?.includes('scope=local')&&accountScope())render();}
async function loadWorkspaceSession(force=false){
 if(sessionRequest)return sessionRequest;
 if(!force&&sessionCheckedAt&&Date.now()-sessionCheckedAt<30000)return workspaceSession;
 const revision=sessionRevision,controller=new AbortController();let timeout;
 sessionRequest=Promise.resolve().then(async()=>{
  try{
   const result=await Promise.race([
    (async()=>{const response=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store',signal:controller.signal});if(response.status===401)return {status:'guest',user:null};if(!response.ok)throw new Error('账户连接暂不可用');const data=await response.json();if(!data.user?.id)throw new Error('账户数据不可用');return {status:'ready',user:data.user};})(),
    new Promise((_,reject)=>{timeout=setTimeout(()=>{controller.abort();reject(new Error('账户连接超时'));},6000);})
   ]);
   if(revision===sessionRevision)workspaceSession=result;
  }catch{if(revision===sessionRevision)workspaceSession={status:'error',user:null};}
  finally{
   clearTimeout(timeout);sessionRequest=null;
   if(revision===sessionRevision){
    sessionCheckedAt=Date.now();updateAccountSession();
    if(homeService&&homeService.user?.id!==workspaceSession.user?.id){homeRequest++;homeService=null;if($('.home-service-side')){$('.home-service-side').innerHTML=homeSide();void loadHomeService();}}
   }
  }
  return workspaceSession;
 });return sessionRequest;
}
async function workspaceServiceFetch(path,options){if(path!=='/api/auth/me'||options?.headers?.['X-PaperKnow-User'])return fetch(path,options);const session=await loadWorkspaceSession();return {ok:session.status==='ready',status:session.status==='ready'?200:session.status==='guest'?401:503,json:async()=>({user:session.user})};}
async function readArtifactSession(){const response=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(6000)});if(response.status===401)return {user:null};if(!response.ok)throw Error('暂时无法确认账户，请稍后重试');const value=await response.json();if(!value.user?.id)throw Error('账户状态无法确认，请重新登录');return value;}
async function signOutWorkspace(){if(sessionSigningOut||!await questionnaireRouteGuard()||!thesisOnlineRouteGuard()||!await onlineWorkspaceConfirmLeave()||!await accountDraftConfirmLeave())return;sessionSigningOut=true;document.querySelectorAll('[data-session-logout]').forEach(button=>button.disabled=true);const controller=new AbortController();let timeout;try{const response=await Promise.race([fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json',...(workspaceSession.user?.id?{'X-PaperKnow-User':workspaceSession.user.id}:{})},credentials:'same-origin',body:'{}',signal:controller.signal}),new Promise((_,reject)=>{timeout=setTimeout(()=>{controller.abort();reject(new Error('退出超时'));},6000);})]);if(!response.ok&&response.status!==401)throw new Error('退出失败');sessionRevision++;workspaceSession={status:'guest',user:null};sessionCheckedAt=Date.now();homeRequest++;homeService=homeService?{cap:homeService.cap,user:null}:null;updateAccountSession();if($('.home-service-side'))$('.home-service-side').innerHTML=homeSide();$('#account-menu').hidden=true;notify('已退出登录，本地草稿与研究偏好仍保留。');}catch{notify('暂时无法退出登录，请检查连接后重试。');}finally{clearTimeout(timeout);sessionSigningOut=false;document.querySelectorAll('[data-session-logout]').forEach(button=>button.disabled=false);}}

