function routeInfo(){const hash=location.hash.slice(1)||'home',at=hash.indexOf('?'),path=at>=0?hash.slice(0,at):hash,params=new URLSearchParams(at>=0?hash.slice(at+1):'');return {parts:path.split('/'),params};}
// Report history is independent of the initial page. Only mounted list/count views need its arrival.
function reportView(){
 if($('.dashboard.home-refresh'))return 'home';
 const {parts:[route]}=routeInfo();
 if(['project','search'].includes(route))return route;
 if(['projects','assets','recent','tasks','membership'].includes(route)&&$('.workspace-scope-tabs a.active'))return $('.workspace-scope-tabs a.active').getAttribute('href').includes('scope=local')?'local':'scope';
 return null;
}
function updateReportsStatus(){
 const main=$('.dashboard'),view=reportView();main?.querySelector('[data-local-reports-status]')?.remove();
 if(!main||!view||!reportsLoading&&(!reportError||view==='local'&&['assets','recent','tasks','membership'].includes(routeInfo().parts[0])))return;
 const note=document.createElement('p');note.dataset.localReportsStatus='';note.className=reportsLoading?'hub-footnote':'hub-error';note.setAttribute('role','status');
 note.textContent=reportsLoading?'正在读取本地比对报告，列表与数量将在读取后更新。':'本地比对报告暂时无法读取，当前列表与数量可能不完整。';
 const heading=main.querySelector(':scope>.hub-heading,:scope>.project-welcome');if(heading)heading.after(note);else main.prepend(note);
}
function refreshReportsView(){
 if(!reportsRefreshPending||reportsLoading||lastRenderedRoute!==location.hash)return;
 const view=reportView();if(!view){reportsRefreshPending=false;return;}
 // Do not run leave guards here: a read finishing must never prompt, save or replace an editing buffer.
 if($('#workspace-dialog')?.open||accountDraftEditing()||onlineWorkspaceHasWork()||editorIsActive()||thesisOnlineHasWork()||revisionHasWork()||helpHasWork()||settingsHasWork()||moreHasWork()||formatHasWork()||researchHasWork()||presentationHasWork())return;
 reportsRefreshPending=false;
 if(view==='home'||view==='scope')withStableView($('.dashboard'),()=>{refreshAssets();if(view==='home')refreshHomePanels();else attachScopeSwitch(routeInfo().parts[0]==='recent'?'assets':routeInfo().parts[0],true);updateReportsStatus();});
 else render();
}
async function loadInitialReports(){
 const previous=reports;
 try{const rows=await repository.all('reports');if(reports===previous){reports=rows.sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));reportError=false;}}
 catch{if(reports===previous)reportError=true;}
 finally{reportsLoading=false;reportsRefreshPending=true;refreshReportsView();}
}

